/**
 * /leaderboard — every catalog bike ranked by its simulated stock time.
 *
 * The data is generated by scripts/gen_stock_leaderboard.py from the physics
 * itself (stock bike, 75 kg rider, the simulator's default conditions), so the
 * board cannot be posted to or gamed. Server component: the JSON is read at
 * build time and only the filtering runs in the browser.
 */

import SiteNav from '../../components/SiteNav';
import SiteFooter from '../../components/SiteFooter';
import PageHeader from '../../components/PageHeader';
import StockBoard from '../../components/StockBoard';
import data from './stock_times.json';

export default function LeaderboardPage() {
  const c = data.conditions || {};
  const conditions = [
    `${Math.round(c.altitude_m)} m above sea level`,
    `${Math.round(c.ambient_temp_c)} °C air`,
    `${Math.round(c.humidity_pct)} % humidity`,
  ].join(', ');
  return (
    <main id="main" className="min-h-screen bg-asphalt-0 text-white">
      <SiteNav />
      <PageHeader
        title="Leaderboard"
        lede={`Every bike in the catalog, stock, with a ${data.rider_kg} kg rider, in the same air: ${conditions}. These are simulated times, not race results.`}
        maxWidth="max-w-5xl"
      />
      <section className="px-4 pb-16 sm:px-6 md:pb-24">
        <div className="mx-auto max-w-5xl">
          <StockBoard bikes={data.bikes} />
        </div>
      </section>
      <SiteFooter />
    </main>
  );
}
